elements.pseudocode:
T = tree with root node x_s
while not timeout:
    if rand() < goalBias:
        x_rand = x_g
    else:
        x_rand = Sample(X_free)
    x_nearest = Nearest(T, x_rand)
    (x_new, m) = ExpandDb(x_nearest, x_rand, X_free, M, delta)
    if x_new != NULL:
        if d(x_new, x_g) < delta:
            AddNode(T, x_new)
            (X_d, U_d) = TracebackTrajectory(T, x_new)
            return (X_d, U_d)  # discontinuity bounded solution
        elif NearestDistance(T, x_new) > delta:
            AddNode(T, x_new)  # avoid nodes too close to existing

M_c = NearestR(x_o, M, delta)  # primitives near origin
m_b = NULL, d_b = infinity
for m in M_c:
    if m is collision_free and d(m.final_state, x_t) < d_b:
        m_b = m
        d_b = d(m.final_state, x_t)
if m_b != NULL:
    return m_b.final_state, m_b
return NULL, NULL

M_c = NearestR(x_o, M, delta)  # primitives near origin
for m in RandomPermutation(M_c):
    if m is collision_free:
        return m.final_state, m
return NULL, NULL
